#!/usr/bin/python3
"""Use Clang for the Vulkan host dispatcher to bound compiler memory.

All code keeps the system libstdc++, C++17 and the same Itanium C++ ABI.
This is a target-local compiler launcher; shader code and glslc are unchanged.
"""
import os
import sys
import hashlib
import json
from pathlib import Path
import re
import subprocess


def embed_shader(source, arguments):
    """Stream exact generated bytes into ELF rodata, avoiding a huge C++ AST."""
    output = Path(arguments[arguments.index('-o') + 1])
    directory = output.parent / 'shader-bytes'
    directory.mkdir(parents=True, exist_ok=True)
    blob = (directory / (source.name + '.bin')).resolve()
    assembly = directory / (source.name + '.S')
    symbols = []; tables = []; offset = 0; expected = None; remaining = None
    with source.open() as lines, blob.open('wb') as binary:
        for line in lines:
            line = line.strip()
            if not line or line == '#include "ggml-vulkan-shaders.hpp"': continue
            if remaining is not None:
                if line == '};':
                    if remaining != 0: raise ValueError('Truncated shader array')
                    remaining = None; expected = None
                    continue
                if not re.fullmatch(r'(?:0x[0-9a-fA-F]{1,2},)+', line):
                    raise ValueError('Unexpected generated shader data')
                data = bytes(int(v,16) for v in line.rstrip(',').split(','))
                if len(data) > remaining: raise ValueError('Oversized shader array')
                binary.write(data); remaining -= len(data); offset += len(data)
                continue
            length = re.fullmatch(r'const uint64_t ([A-Za-z0-9_]+)_len = ([0-9]+);', line)
            if length:
                if expected is not None: raise ValueError('Unpaired shader length')
                expected = (length[1], int(length[2])); continue
            array = re.fullmatch(r'const unsigned char ([A-Za-z0-9_]+)_data\[([0-9]+)\] = \{', line)
            if not array and expected is None and re.fullmatch(r'const (?:void \*\s*|uint64_t )[A-Za-z0-9_]+(?:\[[0-9]+\])+ = [A-Za-z0-9_{}, *]+;', line):
                tables.append(line); continue
            if not array or expected != (array[1], int(array[2])):
                raise ValueError('Unrecognized shader definition')
            remaining = expected[1]
            symbols.append((expected[0], offset, remaining))
    if remaining is not None or expected is not None or not symbols:
        raise ValueError('Incomplete generated shader source')
    if any(c in str(blob) for c in ('"', '\n', '\\')): raise ValueError('Unsafe assembly path')
    code = ['.section .rodata']
    for name, start, length in symbols:
        code += ['.balign 8', f'.global {name}_len', f'.type {name}_len,@object',
                 f'.size {name}_len,8', f'{name}_len:', f'.quad {length}',
                 '.balign 16', f'.global {name}_data', f'.type {name}_data,@object',
                 f'.size {name}_data,{length}', f'{name}_data:', f'.incbin "{blob}",{start},{length}']
    code += ['.section .note.GNU-stack,"",@progbits']
    assembly.write_text('\n'.join(code)+'\n')
    bytes_object = assembly.with_suffix('.o') if tables else output
    subprocess.run(['/usr/bin/cc','-c','-fPIC',str(assembly),'-o',str(bytes_object)],check=True)
    if tables:
        constants = {name+'_len': str(length) for name, _, length in symbols}
        text = '\n'.join(tables)
        text = re.sub(r'\b[A-Za-z0-9_]+_len\b', lambda m: constants.get(m[0], m[0]), text)
        table_source = assembly.with_suffix('.tables.cpp')
        table_source.write_text('#include "ggml-vulkan-shaders.hpp"\n'+text+'\n')
        table_object = assembly.with_suffix('.tables.o')
        subprocess.run(['/usr/bin/clang++','-std=c++17','-O1','-fPIC','-I'+str(source.parent),
                        '-c',str(table_source),'-o',str(table_object)],check=True)
        subprocess.run(['/usr/bin/ld','-r',str(bytes_object),str(table_object),'-o',str(output)],check=True)
    def escape(path): return str(path).replace('\\','\\\\').replace(' ','\\ ').replace('#','\\#').replace('$','$$')
    if '-MF' in arguments:
        dependency = Path(arguments[arguments.index('-MF')+1])
        dependency.write_text(escape(output)+': '+escape(source)+' '+escape(source.parent/'ggml-vulkan-shaders.hpp')+'\n')
    def digest(path):
        with path.open('rb') as stream: return hashlib.file_digest(stream,'sha256').hexdigest()
    manifest = {'source_sha256': digest(source),
                'bytes_sha256': digest(blob),
                'embedded_bytes': offset, 'arrays': len(symbols), 'encoding': 'ELF rodata; exact generated bytes'}
    assembly.with_suffix('.json').write_text(json.dumps(manifest,indent=2)+'\n')

if __name__ == '__main__':
    if len(sys.argv) < 2:
        raise SystemExit('Missing compiler invocation')
    sources = [Path(a) for a in sys.argv[2:] if a.endswith('.comp.cpp')]
    if sources:
        if len(sources) != 1: raise SystemExit('Ambiguous generated shader source')
        embed_shader(sources[0],sys.argv[2:])
        raise SystemExit(0)
    os.execv('/usr/bin/clang++', ['/usr/bin/clang++', *sys.argv[2:]])
